//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");

//#include("../js/controlResize.js"); // 화면 리사이징
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDINS21302.xml";
scwin.nPreRow = -1;
scwin.vISUR_CD21301 = "";
scwin.vISUR_NM21301 = "";
scwin.add_gb21301 = "";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
/********************************************
 *  화면 초기화
 *********************************************/
scwin.fn_Init = function() {
    $c.stf.showObj(txb_param1, false);
    $c.stf.showObj(txb_param2, false);
    $c.stf.showObj(txb_KEY, false);
    $c.stf.showObj(txb_PREPAY_NO, false);
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
};



/********************************************
 *  데이터셋 초기화.
 *********************************************/
scwin.fn_InitDs = function() {
    dts_PayInfo.removeAll();
};
scwin.arrPar = new Array();
/********************************************** 
 * 설명       : 전달값을 설정한다.
 ***********************************************/
scwin.fn_GetParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue(); // 발행기관코드  
    scwin.arrPar[1] = txb_param2.getValue(); // 발행기관코드명     

    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};


/********************************************
 * 선납잔액 조회
 *********************************************/
scwin.fn_listPrepayChg = function(ISUR_CD, COM_NM) {
    // 데이터셋 초기화
    //fn_InitDs();

    // 입력 후 재조회를 위해 세팅
    //if (add_gb21301 == "SEARCH") {
    if (ISUR_CD == "NODATA") {
        ISUR_CD = scwin.vISUR_CD21301;
        txb_ISUR_CD.setValue(scwin.vISUR_CD21301);
        txb_COM_NM.setValue(scwin.vISUR_NM21301);
    } else {
        //전역변수 세팅	
        scwin.vISUR_CD21301 = ISUR_CD;
        //alert("전역변수vISUR_CD21301 :"+vISUR_CD21301);
        scwin.vISUR_NM21301 = COM_NM;
    }

    //alert(vISUR_CD21301+'_'+vISUR_NM21301);

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_PayInfo);

    //선납잔액 조회
    var url = "/PrepayInfoAction.do?method=readPrepayChg";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    if (ISUR_CD == "NODATA") {
        url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    } else {
        url += "&ISUR_CD=" + ISUR_CD;
    }
    //alert(url);
    dts_detail.DataID = encodeURI(url);
    dts_detail.reset();
};


/********************************************
 * 선납금 조회
 *********************************************/
scwin.fn_listPrepayChg3 = function() {
    //선납금등록내역 Grid 조회
    var url = "/PrepayInfoAction.do?method=listPrepayChg";
    url += "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    url += "&SDATE=" + "";
    url += "&EDATE=" + "";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_PayInfo.DataID = encodeURI(url);
    dts_PayInfo.Reset();
};

/********************************************
 * 선납금 조회
 *********************************************/
scwin.fn_listPrepayChg2 = function() {
    //데이터셋 초기화
    scwin.fn_InitDs();

    // Lodaing~~~ 표시
    $c.cm.ShowWin(grd_PayInfo);


    //선납금등록내역 Grid 조회
    var url = "/PrepayInfoAction.do?method=listPrepayChg";
    url += "&ISUR_CD=" + "00000";
    url += "&SDATE=" + "";
    url += "&EDATE=" + "";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_PayInfo.DataID = encodeURI(url);
    dts_PayInfo.Reset();
};


/********************************************
 * 선납금 입력
 *********************************************/
scwin.ins_Insert = function() {
    // 사전체크
    if (!scwin.fn_InputCheck("insert")) {
        return;
    }

    // 입력값 체크(Panel_2)
    if ($c.stf.getObjectValue(rdo_PARAM) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "선급환급구분"));
        rdo_PARAM.focus();
        return;
    }
    if ($c.stf.getObjectValue(edt_SDATE) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "선납/환급일"));
        edt_SDATE.focus();
        return;
    }
    if ($c.bns.fn_CheckDateObj(edt_SDATE, "선납/환급일")) return;
    if ($c.stf.getObjectValue(edt_IO_AMT) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "선납/환급금액"));
        edt_IO_AMT.focus();
        return;
    }
    if ($c.stf.getObjectValue(rdo_PARAM) == "R") {
        //환급
        var vPrepayBal = 0;
        if (txb_PREPAY_BAL.getValue() == "") {
            $c.win.alert("환급할 잔액이 없습니다.");
            rdo_PARAM.focus();
            return;
        } else {
            vPrepayBal = parseInt(txb_PREPAY_BAL.getValue());
        }
        if (parseInt($c.stf.getObjectValue(edt_IO_AMT)) > vPrepayBal) {
            //환급금액이 잔액보다 큰 경우는 마이너스가 되서 안됨
            $c.win.alert("환급금액이 잔액보다 큽니다.");
            edt_IO_AMT.focus();
            return;
        }
    }
    if (!$c.stf.checkMaxLength(txa_REF_CONTN, 200, "비고")) {
        txa_REF_CONTN.focus();
        return false;
    }
    if (!confirm("저장하시겠습니까?")) {
        return;
    }

    //전역변수 세팅	
    scwin.vISUR_CD21301 = txb_ISUR_CD.getValue();
    scwin.vISUR_NM21301 = txb_COM_NM.getValue();
    scwin.add_gb21301 = "SEARCH";
    trs_Save.Action = "/PrepayInfoAction.do?method=registerPrepayAmt" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_Save.KeyName = "toinb_dataid4";
    //trs_Save.KeyValue="JSP(O:pReturnOut=dts_Rst,I:pInput=dts_detail)"; 
    trs_Save.KeyValue = "JSP(I:pInput=dts_PayInfo)";
    trs_Save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_Save.Post();
};



/********************************************
 * 사전체크
 *********************************************/
scwin.fn_InputCheck = function(pGubun) {
    if (txb_ISUR_CD.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행기관코드"));
        txb_ISUR_CD.focus();
        return false;
    }
    if (txb_COM_NM.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행기관명"));
        txb_COM_NM.focus();
        return false;
    }
    return true;
};


/********************************************
 * 신규버튼 클릭
 *********************************************/
scwin.fn_New = function() {
    dts_PayInfo.insertRow();
    dts_PayInfo.setCellData(dts_PayInfo.getRowPosition(), "PREPAY_IO_TP_CD", $c.stf.getObjectValue(rdo_PARAM));
    dts_PayInfo.setCellData(dts_PayInfo.getRowPosition(), "IO_OCCR_DD", $c.stf.getObjectValue(edt_SDATE));
    //alert("edt_IO_AMT: "+getObjectValue(edt_IO_AMT));
    $c.stf.setObjectValue(edt_IO_AMT, $c.stf.getObjectValue(edt_IO_AMT) * (-1));
    if ($c.stf.getObjectValue(edt_IO_AMT) < "0") {
        //음수로 입력한 경우 양수로 전환
        $c.stf.setObjectValue(edt_IO_AMT, $c.stf.getObjectValue(edt_IO_AMT) * (-1));
    }
    dts_PayInfo.setCellData(dts_PayInfo.getRowPosition(), "IO_AMT", $c.stf.getObjectValue(edt_IO_AMT));
    dts_PayInfo.setCellData(dts_PayInfo.getRowPosition(), "MEMO_CONTN", $c.stf.getObjectValue(txa_REF_CONTN));

    //alert("확인");
    txb_ISUR_CD.setValue(scwin.vISUR_CD21301);
    txb_COM_NM.setValue(scwin.vISUR_NM21301);
};


/********************************************
 * 초기화 (발행기관 변경시)
 *********************************************/
scwin.fn_changeInit = function() {
    //발행기관 변경시 데이터 초기화
    //setObjectValue(txb_PREPAY_BAL, "");
    $c.stf.setObjectValue(rdo_PARAM, "");
    $c.stf.setObjectValue(edt_SDATE, "");
    $c.stf.setObjectValue(edt_IO_AMT, "");
    $c.stf.setObjectValue(txb_AmtHan, "");
    $c.stf.setObjectValue(txa_REF_CONTN, "");
};


/********************************************
 * 초기화 (신규 발행기관)
 *********************************************/
scwin.fn_iusrcdsetting = function() {
    $c.win.alert("선납금 정보가 없습니다. 신규로 입력해주세요");
    txb_ISUR_CD.setValue(scwin.vISUR_CD21301);
    txb_COM_NM.setValue(scwin.vISUR_NM21301);
};
scwin.gform_onload = function() {
    scwin.fn_Init();
};
scwin.dts_detail_OnLoadError = function() {
    $c.stf.alert_error(dts_detail);
};
scwin.dts_detail_OnLoadCompleted = function() {
    if (txb_PREPAY_BAL.getValue() == "") {
        scwin.fn_listPrepayChg2(); //신규
        scwin.fn_iusrcdsetting();
    } else {
        scwin.fn_listPrepayChg3(); //기존선급금 존재기관

    }
};
scwin.dts_PayInfo_OnLoadError = function() {
    $c.cm.CloseWin(-1, grd_PayInfo);
    $c.stf.alert_error(dts_PayInfo);
};
scwin.dts_PayInfo_OnLoadCompleted = function(rowcount) {
    if (dts_PayInfo.errorMsg) {
        $c.win.alert(dts_PayInfo.errorMsg);
    } else {
        if (txb_PREPAY_BAL.getValue() == "") {
            txb_TotalCnt.setValue("총 0건"); //신규

        } else {
            txb_TotalCnt.setValue("총 " + rowcount + "건"); //기존선급금 존재기관

        }
    }
    $c.cm.CloseWin(rowcount, grd_PayInfo);

    // 데이터가 없는 경우
    //if( rowcount == 0 ){
    //	fn_CtrlBtn_temp("no_data");
    //}

};
scwin.btn_save_onclick = function() {
    scwin.fn_New();
    scwin.ins_Insert();
};
scwin.trs_Save_OnFail = function() {
    alert_tr_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert("등록이 완료되었습니다.");
    scwin.fn_listPrepayChg("NODATA", "NODATA");
    scwin.fn_changeInit();
};
scwin.btn_ISUR_CD_onclick = function() {
    ins_popupOpen(txb_ISUR_CD, txb_COM_NM, "ULDINS90400", "발행기관 코드", "460", "430");
};
scwin.dts_PayInfo_OnRowPosChanged = function(row) {
    dts_PayInfo.undoRow(scwin.nPreRow);
    scwin.nPreRow = row;
};
scwin.btn_SDATE_onclick = function() {
    popUpCalendar2(edt_SDATE);
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.txb_ISUR_CD_onkeypress = function() {
    if (window.event.keyCode == 13) ins_popupOpen(txb_ISUR_CD, txb_COM_NM, "ULDINS90400", "발행기관 코드", "460", "430");
};
scwin.edt_IO_AMT_OnKeyUp = function(keycode, skeycode) {
    //한글금액표기
    $c.stf.setObjectValue(txb_AmtHan, $c.bns.fn_ChgAmtToHan($c.stf.getObjectValue(edt_IO_AMT)));
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
